src='''def transform(grid):
    h,w=len(grid),len(grid[0])
    hsep=[r for r in range(h) if all(x==4 for x in grid[r])]
    vsep=[c for c in range(w) if all(grid[r][c]==4 for r in range(h))]
    def bands(seps,n):
        out=[];prev=-1
        for s in seps+[n]:
            if s-1>prev: out.append((prev+1,s-1))
            prev=s
        return out
    rbands=bands(hsep,h); vbands=bands(vsep,w)
    bg=9 if 9 in {x for row in grid for x in row} else 5
    pat=None
    for (r0,r1) in rbands:
        for (c0,c1) in vbands:
            cells=[grid[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1)]
            if any(x!=bg for x in cells):
                pat=[row[c0:c1+1] for row in grid[r0:r1+1]]
    if pat is None: return grid
    ph,pw=len(pat),len(pat[0])
    out=[row[:] for row in grid]
    for (r0,r1) in rbands:
        for (c0,c1) in vbands:
            if all(grid[r][c]==bg for r in range(r0,r1+1) for c in range(c0,c1+1)) and (r1-r0+1)==ph and (c1-c0+1)==pw:
                for i in range(ph):
                    for j in range(pw):
                        out[r0+i][c0+j]=pat[i][j]
    return out
'''
